import{alphabetNameControl,bindAlphabetName,stopAlphabetName}from './arabic-alphabet-name-audio.js';
import{esc,toast}from './ui.js';
import{read,write}from './storage.js';
import{ARABIC_LETTERS,RIGHT_JOINING,ALPHABET_SOURCE,letterById,letterForms,normalizeAlphabetProgress,reviewLetter,alphabetQuestion}from './arabic-alphabet-core.js';
const key='arabic-alphabet-progress';
const glyph=(s,cls='')=>'<span class="alphabet-glyph '+cls+'" dir="rtl" lang="ar">'+esc(s)+'</span>';
const back=(href,text)=>'<a class="alphabet-back" href="'+href+'"><img src="./assets/arrow-left.svg" alt="">'+text+'</a>';
export function showArabicAlphabet(host,{hash=location.hash}={}){
 let progress=normalizeAlphabetProgress(read(key,null)),quiz=null;
 const params=new URLSearchParams(hash.split('?')[1]||''),letter=letterById(params.get('letter'));
 function save(p){progress=p;if(!write(key,p))toast('Прогресс не удалось сохранить на этом устройстве.');}
 function rules(){return '<details class="alphabet-rule"><summary>Как соединяются буквы</summary><p>Арабский текст пишется справа налево. Форма буквы зависит от соединения с соседними буквами.</p><div class="alphabet-joining-list">'+RIGHT_JOINING.map(id=>glyph(letterById(id).char)).join('')+'</div><p>Эти шесть букв соединяются с предыдущей буквой справа, но не соединяются со следующей слева. Поэтому у них две формы вместо четырёх.</p></details><details class="alphabet-rule"><summary>Хамза и лям-алиф</summary><div class="alphabet-extra-glyphs">'+['ء','أ','إ','ؤ','ئ'].map(s=>glyph(s)).join('')+'</div><p>Хамза обозначает отдельный звук. Она может писаться отдельно или на опоре. Здесь показаны варианты её написания.</p><div class="alphabet-extra-glyphs">'+glyph('لا')+glyph('ـلا')+'</div><p>Лям-алиф — соединение двух букв: лям и алиф. Это не отдельная буква алфавита.</p></details>';}
 function overview(){
 stopAlphabetName();
 host.innerHTML='<section class="alphabet-page" aria-labelledby="alphabet-title">'+back('#knowledge','Знания')+'<div class="alphabet-topline"><h1 id="alphabet-title">Арабский алфавит</h1><span class="alphabet-count">Повторено '+progress.reviewed.length+'/28</span></div><p>Откройте букву и сравните её формы в слове.</p><details class="alphabet-rule alphabet-download"><summary>Скачать алфавит · PDF</summary><p>Выберите удобный вариант.</p><div class="alphabet-download-options"><a class="button secondary" data-alphabet-pdf="letters" href="./assets/salah-arabic-letters.pdf" download="SALAH-Arabic-Letters.pdf" target="_blank" rel="noopener"><strong>Только буквы</strong><small>Буквы и названия · 1 страница</small></a><a class="button secondary" data-alphabet-pdf="forms" href="./assets/salah-arabic-alphabet.pdf" download="SALAH-Arabic-Alphabet.pdf" target="_blank" rel="noopener"><strong>Буквы и формы в слове</strong><small>Подробная таблица · 2 страницы</small></a></div></details>'+(progress.last?'<a class="button secondary" href="#knowledge?view=alphabet&letter='+progress.last+'">Продолжить · '+esc(letterById(progress.last).name)+'</a>':'')+'<div class="alphabet-grid" aria-label="28 букв арабского алфавита">'+ARABIC_LETTERS.map(l=>'<a class="alphabet-tile '+(progress.reviewed.includes(l.id)?'is-reviewed':'')+'" href="#knowledge?view=alphabet&letter='+l.id+'" aria-label="'+esc(l.name+' · '+l.latin)+'">'+glyph(l.char)+'<small>'+esc(l.name)+'</small></a>').join('')+'</div><button type="button" class="button secondary" data-quiz-start>Проверить себя</button>'+rules()+'<p class="alphabet-note">Отметки повторения сохраняются на этом устройстве.</p><a class="alphabet-source" href="'+ALPHABET_SOURCE+'" target="_blank" rel="noopener">О соединении букв · Unicode</a></section>';
 host.querySelector('[data-quiz-start]').onclick=()=>{quiz={index:0,score:0,start:letterById(progress.last)?.index||0,answered:false};drawQuiz();};window.scrollTo({top:0,behavior:'instant'});
 }
 function study(l){
 stopAlphabetName();
 if(progress.last!==l.id)save({...progress,last:l.id});
 const reviewed=progress.reviewed.includes(l.id);
 host.innerHTML='<section class="alphabet-page" aria-labelledby="alphabet-letter-title">'+back('#knowledge?view=alphabet','Все буквы')+'<div class="alphabet-study"><div class="alphabet-letter-head">'+glyph(l.char)+'<div><h1 id="alphabet-letter-title" tabindex="-1">'+esc(l.name)+'</h1><small>'+esc(l.latin)+'</small></div></div>'+alphabetNameControl(l.id)+'<div class="alphabet-forms" aria-label="Формы буквы">'+letterForms(l).map(f=>'<div class="alphabet-form"><small>'+f.label+'</small>'+glyph(f.text)+'</div>').join('')+'</div><p class="alphabet-note">'+(l.rightOnly?'У этой буквы две формы. Она не соединяется со следующей буквой слева. В середине и конце показана форма с соединением справа.':'Черта показывает место соединения с соседними буквами. Если соседняя буква не соединяется, форма может измениться.')+'</p><div class="alphabet-actions"><button type="button" class="button secondary alphabet-review" data-review aria-pressed="'+reviewed+'">'+(reviewed?'Повторено ✓':'Повторил')+'</button><button type="button" class="button secondary" data-quiz-start>Практика</button></div></div><div class="alphabet-navigation"><button type="button" data-letter-prev '+(l.index===0?'disabled':'')+'>Предыдущая</button><span>'+(l.index+1)+' / 28</span><button type="button" data-letter-next '+(l.index===27?'disabled':'')+'>Следующая</button></div>'+rules()+'<a class="alphabet-source" href="'+ALPHABET_SOURCE+'" target="_blank" rel="noopener">О соединении букв · Unicode</a></section>';
 bindAlphabetName(host,l.id);
 host.querySelector('[data-review]').onclick=()=>{save(reviewLetter(progress,l.id));study(l);host.querySelector('[data-review]').focus();};
 const go=n=>{const next=ARABIC_LETTERS[l.index+n];if(next)location.hash='knowledge?view=alphabet&letter='+next.id;};
 host.querySelector('[data-letter-prev]').onclick=()=>go(-1);host.querySelector('[data-letter-next]').onclick=()=>go(1);
 host.querySelector('[data-quiz-start]').onclick=()=>{quiz={index:0,score:0,start:l.index,answered:false};drawQuiz();};
 }
 function bindQuizBack(){const link=host.querySelector('a[href="#knowledge?view=alphabet"]');if(link)link.onclick=e=>{if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;if(location.hash==='#knowledge?view=alphabet'){e.preventDefault();quiz=null;overview();}};}
 function drawQuiz(){
 stopAlphabetName();
 const q=alphabetQuestion(quiz.index,quiz.start);
 if(!q){host.innerHTML='<section class="alphabet-page">'+back('#knowledge?view=alphabet','Все буквы')+'<div class="alphabet-quiz"><h1>Практика завершена</h1><p>Верных ответов: '+quiz.score+' из 8.</p><p>Повторяйте буквы и обращайте внимание на точки и соединения.</p><button class="button secondary" data-quiz-again>Повторить</button></div></section>';host.querySelector('[data-quiz-again]').onclick=()=>{quiz.index=0;quiz.score=0;quiz.answered=false;drawQuiz();};bindQuizBack();window.scrollTo({top:0,behavior:'instant'});return;}
 host.innerHTML='<section class="alphabet-page">'+back('#knowledge?view=alphabet','Все буквы')+'<div class="alphabet-topline"><h1>Узнайте букву</h1><span class="alphabet-count">'+(quiz.index+1)+' / 8</span></div><div class="alphabet-quiz">'+glyph(q.form.text,'alphabet-quiz-form')+'<div class="alphabet-quiz-choices">'+q.choices.map(c=>'<button type="button" data-answer="'+c.id+'">'+glyph(c.char)+'<span>'+esc(c.name)+'</span><small>'+esc(c.latin)+'</small></button>').join('')+'</div><div class="alphabet-feedback" role="status" aria-live="polite"></div><button type="button" class="button" data-question-next hidden>'+(quiz.index===7?'Результат':'Далее')+'</button></div></section>';
 host.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(quiz.answered)return;quiz.answered=true;const correct=b.dataset.answer===q.target.id;if(correct)quiz.score++;b.classList.add(correct?'is-correct':'is-wrong');host.querySelector('[data-answer="'+q.target.id+'"]').classList.add('is-correct');host.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);host.querySelector('.alphabet-feedback').textContent=(correct?'Верно. ':'Это буква ')+q.target.name+' · '+q.target.latin+'.';host.querySelector('[data-question-next]').hidden=false;});
 host.querySelector('[data-question-next]').onclick=()=>{if(!quiz.answered)return;quiz.index++;quiz.answered=false;drawQuiz();};bindQuizBack();window.scrollTo({top:0,behavior:'instant'});
 }
 if(letter)study(letter);else overview();
}
